  nature TEXT NOT NULL CHECK (nature IN ('Manual', 'Automated', 'IT-dependent manual')),
  frequency TEXT NOT NULL CHECK (frequency IN ('Per transaction', 'Daily', 'Weekly', 'Monthly', 'Quarterly', 'Annual', 'Per event')),
  key_control TEXT NOT NULL CHECK (key_control IN ('Y', 'N'))
);

CREATE TABLE issue (
  issue_id TEXT NOT NULL PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  source TEXT NOT NULL CHECK (source IN ('IA', 'Regulator', 'Self-identified', '2nd line')),
  rating TEXT NOT NULL CHECK (rating IN ('High', 'Medium', 'Low')),
  opened_date TEXT NOT NULL,
  closed_date TEXT
